import{_ as t,o,c as i,a2 as a}from"./chunks/framework.lkcCxhZm.js";const p=JSON.parse('{"title":"AST Layer Architecture Comparison Report","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decision.md","filePath":"architecture/decision.md"}'),n={name:"architecture/decision.md"};function r(l,e,s,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="ast-layer-architecture-comparison-report" tabindex="-1">AST Layer Architecture Comparison Report <a class="header-anchor" href="#ast-layer-architecture-comparison-report" aria-label="Permalink to &quot;AST Layer Architecture Comparison Report&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This report compares two potential architectures for the AST layer of the XML API, focusing on the trade-offs between standard Web API compatibility and source code fidelity.</p><h2 id="option-a-native-dom-integration-jsdom" tabindex="-1">Option A: Native DOM Integration (jsdom) <a class="header-anchor" href="#option-a-native-dom-integration-jsdom" aria-label="Permalink to &quot;Option A: Native DOM Integration (jsdom)&quot;">​</a></h2><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><ul><li>Uses <code>jsdom</code> to create a live <code>XMLDocument</code>.</li><li>Projects <code>XMLAPIModel</code> into the DOM and uses <code>MutationObserver</code> to sync changes back.</li></ul><h3 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h3><ul><li><strong>Fidelity</strong>: <strong>FAILED</strong>. The native <code>XMLSerializer</code> does not preserve: <ul><li>Attribute quote types (converts <code>&#39;</code> to <code>&quot;</code>).</li><li>Extra whitespace between attributes.</li><li>Specific formatting of self-closing tags (e.g., <code>&lt;empty /&gt;</code> becomes <code>&lt;empty/&gt;</code>).</li></ul></li><li><strong>Compatibility</strong>: <strong>HIGH</strong>. Supports all standard DOM methods, <code>querySelector</code>, and can be used with standard XPath engines.</li><li><strong>Complexity</strong>: <strong>MODERATE</strong>. Requires complex mapping and reconciliation between DOM nodes and Model nodes.</li><li><strong>Performance</strong>: <strong>LOW</strong>. Double-parsing and synchronization overhead. Large dependency (<code>jsdom</code>).</li></ul><h2 id="option-b-custom-dom-like-wrapper-duck-typing" tabindex="-1">Option B: Custom DOM-like Wrapper (Duck Typing) <a class="header-anchor" href="#option-b-custom-dom-like-wrapper-duck-typing" aria-label="Permalink to &quot;Option B: Custom DOM-like Wrapper (Duck Typing)&quot;">​</a></h2><h3 id="implementation-1" tabindex="-1">Implementation <a class="header-anchor" href="#implementation-1" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><ul><li>Creates custom classes (<code>CustomElement</code>, <code>CustomText</code>) that implement a subset of the W3C DOM interfaces.</li><li>These wrappers act as a direct proxy to the <code>XMLAPIModel</code>.</li></ul><h3 id="findings-1" tabindex="-1">Findings <a class="header-anchor" href="#findings-1" aria-label="Permalink to &quot;Findings&quot;">​</a></h3><ul><li><strong>Fidelity</strong>: <strong>EXCELLENT</strong>. Since it directly manipulates the <code>XMLAPIModel</code>, we can use our existing <code>Formatter</code> which respects the <code>CST</code> formatting information.</li><li><strong>Compatibility</strong>: <strong>MODERATE</strong>. Supports only the methods we implement. Standard external libraries (like those expecting a real <code>window.Node</code>) may fail unless we achieve high interface coverage.</li><li><strong>Complexity</strong>: <strong>HIGH</strong>. Requires manual implementation of many DOM methods if high compatibility is needed.</li><li><strong>Performance</strong>: <strong>HIGH</strong>. Direct access to the model with zero synchronization latency. No extra dependencies.</li></ul><h2 id="comparison-summary" tabindex="-1">Comparison Summary <a class="header-anchor" href="#comparison-summary" aria-label="Permalink to &quot;Comparison Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Option A (jsdom)</th><th style="text-align:left;">Option B (Custom Wrapper)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Source Fidelity</strong></td><td style="text-align:left;">Poor</td><td style="text-align:left;">Excellent</td></tr><tr><td style="text-align:left;"><strong>API Compatibility</strong></td><td style="text-align:left;">Full</td><td style="text-align:left;">Partial (Subset)</td></tr><tr><td style="text-align:left;"><strong>Performance</strong></td><td style="text-align:left;">Low</td><td style="text-align:left;">High</td></tr><tr><td style="text-align:left;"><strong>Implementation Effort</strong></td><td style="text-align:left;">Moderate</td><td style="text-align:left;">High</td></tr><tr><td style="text-align:left;"><strong>Dependencies</strong></td><td style="text-align:left;">High (jsdom)</td><td style="text-align:left;">None</td></tr></tbody></table><h2 id="final-decision" tabindex="-1">Final Decision <a class="header-anchor" href="#final-decision" aria-label="Permalink to &quot;Final Decision&quot;">​</a></h2><p><strong>Decision: Option B (Custom DOM-like Wrapper)</strong></p><h3 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><p>The primary goal of this project is <strong>Full Fidelity</strong>. Option A fundamentally compromises this goal because native DOM serialization normalizes the XML structure in ways that are incompatible with preserving original formatting.</p><p>Option B allows us to maintain the link between the application&#39;s view (AST) and the source code&#39;s physical structure (CST) through the <code>XMLAPIModel</code>. While it requires more effort to implement DOM-compatible methods, it ensures that automated edits &quot;blend seamlessly with the existing code style&quot; as required by the project goals.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Implement formal <code>Node</code>, <code>Element</code>, <code>Document</code> interfaces in <code>src/ast/</code>.</li><li>Develop a query engine (querySelector) for the custom AST.</li><li>Integrate with existing <code>XMLAPIModel</code> reconciliation logic.</li></ul>',22)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
